<?php
declare(strict_types=1);
if(!defined('HOGAR_INTERNAL')){http_response_code(404);exit;}
$db->exec('CREATE TABLE IF NOT EXISTS property_metrics(property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,day TEXT NOT NULL,views INTEGER NOT NULL DEFAULT 0,contacts INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(property_id,day));CREATE TABLE IF NOT EXISTS property_metric_seen(property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,day TEXT NOT NULL,kind TEXT NOT NULL,visitor TEXT NOT NULL,PRIMARY KEY(property_id,day,kind,visitor));');
function metricDay(): string {return (new DateTimeImmutable('now',new DateTimeZone('America/Mexico_City')))->format('Y-m-d');}
function metricRange(): array {$days=$_GET['days']??'all';if(!is_string($days)||!in_array($days,['all','7','30'],true))fail('Elige un periodo válido.',422);$today=new DateTimeImmutable('today',new DateTimeZone('America/Mexico_City'));$start=$days==='all'?null:$today->modify('-'.((int)$days-1).' days');return ['days'=>$days,'from'=>$start?->format('Y-m-d'),'to'=>$today->format('Y-m-d'),'start'=>$start?->getTimestamp(),'end'=>$today->modify('+1 day')->getTimestamp()];}
function metricValues(?string $id,array $range): array {$where=[];$params=[];if($id!==null){$where[]='property_id=?';$params[]=$id;}$dates=$where;$dp=$params;if($range['from']!==null){$dates[]='day>=?';$dp[]=$range['from'];}$dates[]='day<=?';$dp[]=$range['to'];$v=query('SELECT COALESCE(SUM(views),0) AS views,COALESCE(SUM(contacts),0) AS contacts FROM property_metrics WHERE '.implode(' AND ',$dates),$dp)->fetch();if($range['start']!==null){$where[]='created>=?';$params[]=$range['start'];}$where[]='created<?';$params[]=$range['end'];return ['views'=>(int)$v['views'],'contacts'=>(int)$v['contacts'],'favorites'=>(int)query('SELECT COUNT(*) FROM property_favorites WHERE '.implode(' AND ',$where),$params)->fetchColumn()];}
function metricSeries(?string $id,array $range): array {
 global $db;$where=$id!==null?'property_id=? AND ':'';$params=$id!==null?[$id]:[];
 $rows=query('SELECT day,SUM(views) AS views,SUM(contacts) AS contacts FROM property_metrics WHERE '.$where.'day<=?'.($range['from']!==null?' AND day>=?':'').' GROUP BY day ORDER BY day',array_merge($params,[$range['to']],$range['from']!==null?[$range['from']]:[]))->fetchAll();$daily=[];foreach($rows as $row)$daily[$row['day']]=['views'=>(int)$row['views'],'contacts'=>(int)$row['contacts'],'favorites'=>0];
 $db->sqliteCreateFunction('metric_local_day',fn($t)=>(new DateTimeImmutable('@'.(int)$t))->setTimezone(new DateTimeZone('America/Mexico_City'))->format('Y-m-d'),1);
 $f=query('SELECT metric_local_day(created) AS day,COUNT(*) AS count FROM property_favorites WHERE '.$where.'created<?'.($range['start']!==null?' AND created>=?':'').' GROUP BY day',array_merge($params,[$range['end']],$range['start']!==null?[$range['start']]:[]))->fetchAll();foreach($f as $row){$daily[$row['day']]??=['views'=>0,'contacts'=>0,'favorites'=>0];$daily[$row['day']]['favorites']=(int)$row['count'];}
 ksort($daily);$start=$range['from']??(array_key_first($daily)??$range['to']);$day=new DateTimeImmutable($start,new DateTimeZone('America/Mexico_City'));$result=[];while($day->format('Y-m-d')<=$range['to']){$key=$day->format('Y-m-d');$result[]=['day'=>$key]+($daily[$key]??['views'=>0,'contacts'=>0,'favorites'=>0]);$day=$day->modify('+1 day');}return $result;
}
function metricComparison(?string $id,array $range): ?array {
 if($range['days']==='all')return null;$start=new DateTimeImmutable($range['from'],new DateTimeZone('America/Mexico_City'));$before=$start->modify('-'.$range['days'].' days');$previous=['days'=>$range['days'],'from'=>$before->format('Y-m-d'),'to'=>$start->modify('-1 day')->format('Y-m-d'),'start'=>$before->getTimestamp(),'end'=>$start->getTimestamp()];$current=metricValues($id,$range);$old=metricValues($id,$previous);$changes=[];foreach(['views','favorites','contacts'] as $key){$delta=$current[$key]-$old[$key];$changes[$key]=['previous'=>$old[$key],'delta'=>$delta,'percent'=>$old[$key]>0?round($delta/$old[$key]*100,1):($delta===0?0:null)];}return ['from'=>$previous['from'],'to'=>$previous['to'],'changes'=>$changes];
}
function handlePropertyStats(string $action,string $method,array $input): void {
 if($action==='property-metric'&&$method==='POST'){
  $id=$input['id']??'';$kind=$input['kind']??'';if(!is_string($id)||!preg_match('/^[a-f0-9]{24}$/D',$id)||!in_array($kind,['view','contact'],true))fail('Evento inválido.',422);
  $p=selectProperty($id);if(!$p||$p['status']!=='active'||$p['owner_status']!=='active')fail('Anuncio no disponible.',404);$u=user();if((int)($u['id']??0)===(int)$p['user_id']||isSuperadmin($u))reply(['recorded'=>false]);
  limitRate('property-metric',500,3600);global $db;$day=metricDay();$visitor=hash('sha256',session_id().'|'.$day);$db->beginTransaction();try{query('DELETE FROM property_metric_seen WHERE day<=?',[(new DateTimeImmutable('-2 days',new DateTimeZone('America/Mexico_City')))->format('Y-m-d')]);$q=query('INSERT OR IGNORE INTO property_metric_seen(property_id,day,kind,visitor) VALUES(?,?,?,?)',[$id,$day,$kind,$visitor]);$recorded=$q->rowCount()>0;if($recorded){$field=$kind==='view'?'views':'contacts';query('INSERT INTO property_metrics(property_id,day,'.$field.') VALUES(?,?,1) ON CONFLICT(property_id,day) DO UPDATE SET '.$field.'='.$field.'+1',[$id,$day]);}$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}reply(['recorded'=>$recorded]);
 }
 if($action==='property-stats'&&$method==='GET'){$u=requireUser();if(!billingHasAnalytics($u))fail('Las estadísticas de tus propiedades están incluidas en Asesor Plus, hasta 25 propiedades por $199 al mes.',403);$id=$_GET['id']??'';if(!is_string($id))fail('Anuncio no disponible.',404);$p=query('SELECT id,title FROM properties WHERE id=? AND user_id=?',[$id,$u['id']])->fetch();if(!$p)fail('Anuncio no disponible.',404);reply(['property'=>$p,'metrics'=>metricValues($id,$range=metricRange()),'range'=>$range,'series'=>metricSeries($id,$range),'comparison'=>metricComparison($id,$range)]);}
 if($action==='admin-statistics'&&$method==='GET'){$u=requireUser();if(!isSuperadmin($u))fail('Acceso reservado.',403);$range=metricRange();$page=max(1,min(10000,(int)($_GET['page']??1)));$total=(int)query('SELECT COUNT(*) FROM properties WHERE status!="draft"')->fetchColumn();$rows=query('SELECT id,title,operation,status FROM properties WHERE status!="draft" ORDER BY created DESC,id DESC LIMIT 20 OFFSET '.(($page-1)*20))->fetchAll();foreach($rows as &$row){$row['metrics']=metricValues($row['id'],$range);$row['comparison']=metricComparison($row['id'],$range);}unset($row);reply(['items'=>$rows,'metrics'=>metricValues(null,$range),'range'=>$range,'series'=>metricSeries(null,$range),'comparison'=>metricComparison(null,$range),'page'=>$page,'pages'=>(int)ceil($total/20)]);}
}
